head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/utils.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/libRoundPanel.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/stf.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/session.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/controlResize.js"); // 화면 리사이징

scwin.vScrenID = "ULDFIS00200_03.gfm";
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsStrtDt = ""; // 조회조건 결산일자 시작
scwin.vAcntclsEndDt = "";
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
}; // 조회조건 결산일자 종료

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    // 결산일자 조회
    //결산일자 검색(FROM-TO)로 변경되어 아래 로직 삭제
    // frame.Provider("../frame_head").fn_SrchAcntclsDt();

    scwin.fn_Search();
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_MajShrhd.removeAll();
};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    //필수항목 체크.

	//----W-Craft WebSquare 변환 확인: fn_GetKisCd----//
    scwin.vKisCd = $c.frame.path("../frame_head").fn_GetKisCd();

	//----W-Craft WebSquare 변환 확인: fn_GetAcntclsStrtDt----//
    scwin.vAcntclsStrtDt = $c.frame.path("../frame_head").fn_GetAcntclsStrtDt();

	//----W-Craft WebSquare 변환 확인: fn_GetAcntclsEndDt----//
    scwin.vAcntclsEndDt = $c.frame.path("../frame_head").fn_GetAcntclsEndDt();
    if (scwin.vKisCd == "" || scwin.vAcntclsStrtDt == "" || scwin.vAcntclsEndDt == "") {
        return false;
    }
    return true;
};


/**
 * 주요주주 조회
 */
scwin.fn_Search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_MajShrhd);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.MajShrhd" + "&outputMessageId=FIS_MAJ_SHRHD" + "&param01=" + scwin.vKisCd + "&param02=" + scwin.vAcntclsStrtDt + "&param03=" + scwin.vAcntclsEndDt;
    dts_MajShrhd.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_MajShrhd.Reset();
};


/**
 *  엑셀파일다운로드
 */
scwin.fn_excel_download = function() {
    if (dts_MajShrhd.getTotalRow() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_MajShrhd, "주요주주", "", "1");
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.dts_MajShrhd_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_MajShrhd);
    $c.stf.alert_error(dts_MajShrhd);
};
scwin.dts_MajShrhd_OnLoadCompleted = function(rowcount) {
    if (dts_MajShrhd.errorMsg) {
        alert(dts_MajShrhd.errorMsg);
    }
    $c.cm.CloseWin(rowcount, grd_MajShrhd);
};
